input.script:
export const meta = {
  name: 'alpha-beta-pair',
  description: 'Two agents, no tools: one replies alpha, the other replies beta',
  phases: [{ title: 'Reply' }],
}

phase('Reply')
const [a, b] = await parallel([
  () => agent('Reply with exactly one word: alpha. Use no tools.', { label: 'agent-alpha', phase: 'Reply' }),
  () => agent('Reply with exactly one word: beta. Use no tools.', { label: 'agent-beta', phase: 'Reply' }),
])
return { alpha: a, beta: b }

